KG_CODE("f:src/autoskill/workflow.py","\"\"\"Criteria-driven queue processing — the logic, with the task declared apart.\n\nThe problem this solves\n-----------------------\nThe Oracle approval runner worked, and it was the wrong shape. Its knowledge\nof *that* queue — which link is a work item, which cell means \"family\", which\nbutton commits — was welded into the code that walks a list, dedupes, opens\nan item, decides and acts. Every other queue on earth has exactly the same\nshape and entirely different strings, so the shape could not be reused.\n\nHere the two are separated for good:\n\n    profile (JSON)  —  WHAT counts: patterns, gates, the action sequence\n    engine (this)   —  HOW it is done: walk, dedupe, classify, act, record\n\nNothing in this module names a site, a system or a field. Point it at a\nmoderation queue, a ticket triage, an inbox, an approval list — same engine,\ndifferent criteria.\n\nThe decision rule\n-----------------\nGates run in order and **APPROVE is only reachable when every gate passes**.\nThat direction is deliberate and was paid for: the original rule was \"if it\ndoes not look excluded, act\", which reads \"no evidence\" as \"no problem\". A\npage that has painted its action button but not yet its detail rows contains\nno exclusion marker at all, so an unfinished read approved things the policy\nsaid to skip — irreversibly, unattended.\n\n    complete   the observation really contains the detail region\n    exclude    none of the exclusion patterns matched\n    identify   a recognised case was found, so the record can name it\n\nAnything else is skipped and recorded as skipped. A wrongly skipped item costs\na human one click; a wrongly committed one cannot be taken back.\n\nDurability\n----------\nOne step in the sequence is marked `commit`: the irreversible one. The intent\nis journalled with `fsync` *before* that step and the outcome after, so a lost\nspreadsheet row, a crash or a power cut can never hide that it was dispatched.\nThe journal is the record of truth; any workbook is a view of it, rebuildable\nwith `--reconcile`.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport os\nimport re\nimport time\nfrom dataclasses import dataclass, field\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Any\n\nfrom .protocol import EffectState, ErrorCode, Method, ProtocolError\n\n# Opening this many rows only to find them already decided means the list\n# is behind the truth; reloading it beats walking it, and re-sorts new\n# arrivals into view.\nSTALE_ROWS_BEFORE_RELOAD = 5\n\n# How long a step's effect is waited for before it counts as missing. A single\n# look at a fixed moment is not a measurement: the evidence check used to sleep\n# 2s and look once, and a Claim that takes ~18s to register was judged to have\n# done nothing - 20 claimable requests were retired that way (F-21). The page\n# is polled until the control goes or this budget runs out; a step may declare\n# its own `proves_within` when its effect is known to take longer.\nEVIDENCE_WITHIN_S = 30.0\nEVIDENCE_POLL_S = 2.0\n\n# A wait that follows a click is split: after this many seconds without the\n# awaited control, the click is pressed once more if its control is still on\n# the page, and the rest of the budget is waited. Measured in the T5 live run\n# (S136): 5 of 8 first Claim clicks changed nothing for 90 s, and a second\n# click on the same button showed Approve within 6 s every time. A step may\n# set `reclick_after` (0 turns it off).\nRECLICK_AFTER_S = 30.0\n# After a reload-and-restart of an item, how long the page gets to come back.\nRELOAD_SETTLE_S = 8.0\n# An item whose page could not be read this many times in a row is held for\n# the rest of the run: not decided (the journal says `failed`, and the next\n# run tries it again), just not reopened. T10 (S141) reopened one unreadable\n# record 14 times in 10 minutes, all identical failures.\nUNREAD_HOLD_AFTER = 3\n# The main tab gone (T5-5: closed from outside the tool): reopen `home_url`,\n# at most this often, instead of waiting for ever for a tab nobody will open.\nMAIN_REOPEN_EVERY_S = 300.0\n\nSURFACES = (\"rb\", \"browser\")\nVERDICTS = (\"act\", \"skip\", \"incomplete\", \"done\", \"blocked\")\n\n\n# --- profile -----------------------------------------------------------------\n\n@dataclass\nclass Gate:\n    name: str\n    kind: str                       # all_of | any_of | capture\n    patterns: list[str] = field(default_factory=list)\n    label: str = \"\"\n    on_match: str = \"skip\"          # for any_of: what a match means\n    retry_after_s: float = 0.0\n    capture_into: str = \"\"\n\n    @staticmethod\n    def from_dict(d: dict[str, Any]) -> Gate:\n        kind = next((k for k in (\"all_of\", \"any_of\", \"capture\") if k in d), \"\")\n        if not kind:\n            raise ValueError(f\"gate {d.get('name', '?')!r} needs all_of, \"\n                             f\"any_of or capture\")\n        pats = d[kind]\n        return Gate(name=str(d.get(\"name\") or kind), kind=kind,\n                    patterns=[pats] if isinstance(pats, str) else list(pats),\n                    label=str(d.get(\"label\") or \"\"),\n                    on_match=str(d.get(\"on_match\") or \"skip\"),\n                    retry_after_s=float(d.get(\"retry_after_s\") or 0),\n                    capture_into=str(d.get(\"into\") or \"summary\"))\n\n\n@dataclass\nclass Step:\n    kind: str                       # click | type | wait | observe | sleep\n    pattern: str = \"\"\n    text: str = \"\"\n    name: str = \"\"\n    role: str = \"\"\n    timeout: float = 30.0\n    seconds: float = 0.0\n    optional: bool = False\n    commit: bool = False\n    # Evidence the step actually did something. `proves` must be GONE\n    # afterwards: a control still present is a control that did not\n    # fire. Without it, a click that dispatched correctly and changed\n    # nothing is indistinguishable from one that worked, and the cost\n    # is paid later as a timeout on a step that could never succeed.\n    proves: str = \"\"\n    proves_label: str = \"\"\n    # Seconds the effect may take to show; 0 means EVIDENCE_WITHIN_S.\n    proves_within: float = 0.0\n    # For a `wait` after a click: re-press the click after this many seconds\n    # (see RECLICK_AFTER_S). -1 means the default; 0 turns it off.\n    reclick_after: float = -1.0\n    # S141, for pages whose controls have no name or whose tree cannot be\n    # read: press the control in the row of the drawn text `near` (chosen by\n    # `pick`: right/left/N/name:WORD, `nth` occurrence of the text) through\n    # `rb.act`. `expect_download`: the step is proved by a new file in the\n    # downloads folder (a download changes no page).\n    near: str = \"\"\n    pick: str = \"\"\n    nth: int = 1\n    expect_download: bool = False\n\n    @staticmethod\n    def from_dict(d: dict[str, Any]) -> Step:\n        kind = str(d.get(\"do\") or \"\")\n        if kind not in (\"click\", \"type\", \"wait\", \"observe\", \"sleep\"):\n            raise ValueError(f\"unknown step {kind!r}; use click, type, wait, \"\n                             f\"observe or sleep\")\n        return Step(kind=kind, pattern=str(d.get(\"match\") or \"\"),\n                    text=str(d.get(\"text\") or \"\"), name=str(d.get(\"name\") or \"\"),\n                    role=str(d.get(\"role\") or \"\"),\n                    timeout=float(d.get(\"timeout\") or 30),\n                    seconds=float(d.get(\"seconds\") or 0),\n                    optional=bool(d.get(\"optional\")),\n                    commit=bool(d.get(\"commit\")),\n                    proves=str(d.get(\"proves\") or \"\"),\n                    proves_label=str(d.get(\"proves_label\") or \"\"),\n                    proves_within=float(d.get(\"proves_within\") or 0),\n                    reclick_after=float(d[\"reclick_after\"])\n                    if d.get(\"reclick_after\") is not None else -1.0,\n                    near=str(d.get(\"near\") or \"\"),\n                    pick=str(d.get(\"pick\") or \"\"),\n                    nth=int(d.get(\"nth\") or 1),\n                    expect_download=bool(d.get(\"expect_download\")))\n\n\n@dataclass\nclass Profile:\n    name: str\n    description: str = \"\"\n    surface: str = \"rb\"\n    main_tab: str = \"\"\n    item: str = \"\"\n    load_more: str = \"\"\n    identity: str = \"\"\n    # Same parameter, read from the row's href instead of the opened\n    # tab's URL. When it works, an already-decided row costs nothing.\n    identity_in_href: bool = True\n    # A known-good starting URL. Reloading the tab keeps whatever\n    # session state its current URL carries, which is the very thing\n    # that goes stale; going home discards it.\n    home_url: str = \"\"\n    reach: list[Step] = field(default_factory=list)\n    subject: str = \"\"\n    gates: list[Gate] = field(default_factory=list)\n    steps: list[Step] = field(default_factory=list)\n    ledger_file: str = \"\"\n    ledger_header: str = \"Session\\tItem\\tSubject\\tAction\"\n    maintenance_every: int = 25\n    settle_s: float = 5.0\n    # Before the irreversible step, a failed item may be reloaded once and\n    # its steps started again. After `committing` is written, never.\n    reload_to_recover: bool = True\n    # How a click is pressed. \"click\": one input event, as always. \"ladder\":\n    # through `rb.act` - the page must visibly answer, a silent method is\n    # pressed again and the next one tried (act.py); the commit step is sent\n    # ONCE (irreversible) and its own `proves` still decides `acted`.\n    press: str = \"click\"\n    press_patience: float = 15.0\n    # S141, for lists whose tree cannot be read and whose rows open in place:\n    #   read \"pixels\" - the list and the item are read with the pixel\n    #     fallback (OCR lines `ocr [x,y wxh] \"text\"`) when the tree times out;\n    #   opens \"same-tab\" - a row opens its item in the SAME tab (by the\n    #     control `open_pick` of the row), and the list is reached again after;\n    #   identity_from \"text\" - the item's identity is its row text, so it is\n    #     never processed twice without an id in any URL.\n    read: str = \"tree\"\n    opens: str = \"tab\"\n    open_pick: str = \"right\"\n    identity_from: str = \"url\"\n    path: Path | None = None\n\n    @staticmethod\n    def load(path: str | Path) -> Profile:\n        p = Path(path)\n        if not p.exists():\n            raise ProtocolError(ErrorCode.TARGET_NOT_FOUND,\n                                f\"no such profile: {p}\",\n                                hint=\"Run `auto flow list` to see what is \"\n                                     \"installed.\")\n        return Profile.from_dict(json.loads(p.read_text(encoding=\"utf-8\")), p)\n\n    @staticmethod\n    def from_dict(d: dict[str, Any], path: Path | None = None) -> Profile:\n        lst = d.get(\"list\") or {}\n        led = d.get(\"ledger\") or {}\n        surface = str(d.get(\"surface\") or \"rb\")\n        if surface not in SURFACES:\n            raise ValueError(f\"surface must be one of {SURFACES}\")\n        prof = Profile(\n            name=str(d.get(\"name\") or (path.stem if path else \"unnamed\")),\n            description=str(d.get(\"description\") or \"\"),\n            surface=surface,\n            main_tab=str(lst.get(\"main_tab\") or \"\"),\n            item=str(lst.get(\"item\") or \"\"),\n            load_more=str(lst.get(\"load_more\") or \"\"),\n            identity=str(lst.get(\"identity_param\") or \"\"),\n            reach=[Step.from_dict(s) for s in (lst.get(\"reach\") or [])],\n            identity_in_href=bool(lst.get(\"identity_in_href\", True)),\n            home_url=str(lst.get(\"home_url\") or \"\"),\n            subject=str(d.get(\"subject\") or \"\"),\n            gates=[Gate.from_dict(g) for g in (d.get(\"gates\") or [])],\n            steps=[Step.from_dict(s) for s in (d.get(\"steps\") or [])],\n            ledger_file=str(led.get(\"file\") or \"\"),\n            ledger_header=str(led.get(\"header\") or \"Session\\tItem\\tSubject\\tAction\"),\n            maintenance_every=int(d.get(\"maintenance_every\") or 25),\n            settle_s=float(d.get(\"settle_s\") or 5),\n            reload_to_recover=bool(d.get(\"reload_to_recover\", True)),\n            press=str(d.get(\"press\") or \"click\"),\n            press_patience=float(d.get(\"press_patience\") or 15),\n            read=str(lst.get(\"read\") or \"tree\"),\n            opens=str(lst.get(\"opens\") or \"tab\"),\n            open_pick=str(lst.get(\"open_pick\") or \"right\"),\n            identity_from=str(lst.get(\"identity_from\") or \"url\"),\n            path=path)\n        prof.validate()\n        return prof\n\n    def validate(self) -> list[str]:\n        \"\"\"Fail loudly at load time, not on the first live item.\"\"\"\n        problems: list[str] = []\n        if not self.item:\n            problems.append(\"list.item is required: the pattern that matches \"\n                            \"one work item in an observation\")\n        for pat in ([self.item, self.load_more, self.subject]\n                    + [p for g in self.gates for p in g.patterns]\n                    + [s.pattern for s in self.steps]\n                    + [s.pattern for s in self.reach]\n                    + [s.proves for s in self.steps + self.reach]):\n            if pat:\n                try:\n                    re.compile(pat)\n                except re.error as exc:\n                    problems.append(f\"bad regex {pat[:40]!r}: {exc}\")\n        if not any(s.commit for s in self.steps) and self.steps:\n            problems.append('no step is marked \"commit\": the engine needs to '\n                            \"know which one is irreversible so it can journal \"\n                            \"the intent before it\")\n        if len([s for s in self.steps if s.commit]) > 1:\n            problems.append('more than one step is marked \"commit\"')\n        for s in self.steps:\n            if s.commit and s.kind == \"click\" and not s.proves \\\n                    and not (s.near and s.expect_download):\n                # Without it `acted` is written the moment the click is\n                # dispatched: an approval recorded on faith, and `decided`\n                # closes the item for ever even if the click was swallowed.\n                problems.append('the \"commit\" step declares no \"proves\": '\n                                \"name the control that must be GONE once it \"\n                                \"has worked, or an unconfirmed click is \"\n                                \"recorded as done\")\n        if self.press not in (\"click\", \"ladder\"):\n            problems.append(f'\"press\" must be \"click\" or \"ladder\", not {self.press!r}')\n        if self.press == \"ladder\" and self.surface != \"rb\":\n            problems.append('\"press\": \"ladder\" needs the rb surface (rb.act)')\n        if self.read not in (\"tree\", \"pixels\"):\n            problems.append(f'list \"read\" must be \"tree\" or \"pixels\", not {self.read!r}')\n        if self.opens not in (\"tab\", \"same-tab\"):\n            problems.append(f'list \"opens\" must be \"tab\" or \"same-tab\", not {self.opens!r}')\n        if self.identity_from not in (\"url\", \"text\"):\n            problems.append('list \"identity_from\" must be \"url\" or \"text\"')\n        uses_rb_only = (self.read == \"pixels\" or self.opens == \"same-tab\"\n                        or any(st.near for st in self.steps + self.reach))\n        if uses_rb_only and self.surface != \"rb\":\n            problems.append('pixel reading, same-tab items and \"near\" steps '\n                            'need the rb surface')\n        if self.opens == \"same-tab\" and not self.home_url:\n            problems.append('\"opens\": \"same-tab\" needs list.home_url: the '\n                            'list is reached again from there after each item')\n        for g in self.gates:\n            if g.kind == \"capture\" and len(g.patterns) != 1:\n                problems.append(f\"gate {g.name!r}: capture takes one pattern\")\n        if problems:\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED,\n                f\"profile {self.name!r} is not usable: \" + \"; \".join(problems),\n                hint=\"Fix the profile and re-run `auto flow validate`.\")\n        return problems\n\n    def summary(self) -> dict[str, Any]:\n        return {\"name\": self.name, \"description\": self.description,\n                \"surface\": self.surface, \"gates\": [g.name for g in self.gates],\n                \"steps\": [s.kind + (\"*\" if s.commit else \"\") for s in self.steps],\n                \"reach\": [s.kind for s in self.reach],\n                \"ledger\": self.ledger_file or None,\n                \"path\": str(self.path) if self.path else None}\n\n\ndef profiles_dir() -> Path:\n    from .resources import asset\n    return asset(\"skill/profiles\")\n\n\ndef list_profiles() -> list[dict[str, Any]]:\n    out: list[dict[str, Any]] = []\n    d = profiles_dir()\n    if not d.exists():\n        return out\n    for p in sorted(d.glob(\"*.json\")):\n        try:\n            out.append(Profile.load(p).summary())\n        except Exception as exc:                  # noqa: BLE001\n            out.append({\"name\": p.stem, \"path\": str(p),\n                        \"error\": f\"{type(exc).__name__}: {exc}\"})\n    return out\n\n\n# --- classification ----------------------------------------------------------\n\n@dataclass\nclass Verdict:\n    outcome: str                    # act | skip | incomplete\n    label: str\n    subject: str = \"\"\n    gate: str = \"\"\n\n\ndef classify(profile: Profile, body: str) -> Verdict:\n    \"\"\"Run the gates in order. `act` is only reachable if all of them pass.\"\"\"\n    subject = \"\"\n    if profile.subject:\n        m = re.search(profile.subject, body)\n        if m:\n            subject = (m.group(1) if m.groups() else m.group(0)).strip()\n\n    label = \"\"\n    for g in profile.gates:\n        if g.kind == \"all_of\":\n            if not all(re.search(p, body) for p in g.patterns):\n                return Verdict(\"incomplete\", g.label or f\"{g.name} not satisfied\",\n                               subject, g.name)\n        elif g.kind == \"any_of\":\n            hit = next((p for p in g.patterns if re.search(p, body)), None)\n            if hit:\n                detail = \"\"\n                m = re.search(hit, body)\n                if m and m.groups():\n                    detail = f\" - {m.group(1).strip()[:60]}\"\n                return Verdict(g.on_match, (g.label or g.name) + detail,\n                               subject, g.name)\n        else:                                      # capture\n            m = re.search(g.patterns[0], body)\n            if not m:\n                return Verdict(\"skip\", g.label or f\"{g.name} not recognised\",\n                               subject, g.name)\n            label = (m.group(1) if m.groups() else m.group(0)).strip()[:70]\n    return Verdict(\"act\", label or \"item\", subject, \"\")\n\n\n# --- the runner --------------------------------------------------------------\n\n_SIGNALLED: list[str] = []\n\n\ndef request_stop_via_signal(reason: str = \"interrupt\") -> None:\n    \"\"\"Record that a stop was asked for. Safe to call from a signal handler.\"\"\"\n    if not _SIGNALLED:\n        _SIGNALLED.append(reason)\n\n\ndef install_signal_stop() -> None:\n    \"\"\"Make Ctrl-C and a polite kill mean \"finish this item, then stop\".\n\n    Without this, SIGINT raises KeyboardInterrupt wherever the run happens to\n    be - possibly between an irreversible click and the journal line that\n    records it. The handler only sets a flag; the loop decides where to act\n    on it.\n    \"\"\"\n    import signal\n    for name in (\"SIGINT\", \"SIGTERM\", \"SIGBREAK\"):\n        sig = getattr(signal, name, None)\n        if sig is None:\n            continue\n        try:\n            signal.signal(sig, lambda *_a, n=name: request_stop_via_signal(n))\n        except (ValueError, OSError):\n            pass          # not the main thread, or not supported here\n\n\ndef stop_file_for(home: Path, profile_name: str) -> Path:\n    return Path(home) / f\"flow-{profile_name}.stop\"\n\n\nclass _Unconfirmed(Exception):\n    \"\"\"The irreversible step ran and could not be confirmed.\n\n    Deliberately neither `acted` nor `failed`. `failed` asserts nothing\n    happened; `acted` asserts it did; here neither is known. The journal\n    already models exactly this: a `committing` with no `acted` is the\n    honest unknown, and `decided()` counts it so the item is never retried\n    blind. So nothing further is written - the gap IS the record.\n    \"\"\"\n\n\nclass _NoEffect(Exception):\n    \"\"\"A step ran cleanly and its effect never appeared.\n\n    Distinct from a ProtocolError on purpose: nothing malfunctioned. But it\n    is NOT a decision about the item. \"The control is still there\" cannot\n    tell \"this request is not mine\" from \"my click never landed\" - 118 dead\n    clicks were logged in one day (O-02) - and recording it as `skipped`\n    retired claimable requests for ever (F-21). It is journalled `failed`,\n    which `decided()` does not count, so a later run judges the item again.\n    \"\"\"\n\n\nclass FlowRunner:\n    \"\"\"Walks a queue described by a profile. Knows nothing about any site.\"\"\"\n\n    def __init__(self, profile: Profile, *, home: Path, session_tag: str = \"S1\",\n                 dry_run: bool = False, on_event=print) -> None:\n        self.p = profile\n        self.home = home\n        self.tag = session_tag\n        self.dry_run = dry_run\n        self.emit = on_event\n        led = Path(profile.ledger_file).expanduser() if profile.ledger_file else None\n        self.ledger = led\n        self.journal = (led.with_suffix(\".journal.jsonl\") if led\n                        else home / f\"flow-{profile.name}.journal.jsonl\")\n        self._last_tab: int | None = None\n        self._main_reopened_at: float | None = None\n        self.stop_file = stop_file_for(home, profile.name)\n        self._stop_reason: str | None = None\n        self._unread: dict[str, int] = {}   # identity -> unread in a row\n        self._held: set[str] = set()        # held for this run (see above)\n\n    def _note_read(self, identity: str, unread: bool) -> None:\n        \"\"\"Count pages that could not be read; after UNREAD_HOLD_AFTER in a\n        row the item is held for the rest of this run. A page that was read\n        clears the count.\"\"\"\n        if not identity:\n            return\n        if not unread:\n            self._unread.pop(identity, None)\n            return\n        n = self._unread[identity] = self._unread.get(identity, 0) + 1\n        if n >= UNREAD_HOLD_AFTER and identity not in self._held:\n            self._held.add(identity)\n            self.emit(f\"  {identity[:24]}: unread {n} times in a row - held \"\n                      f\"for the rest of this run (not decided; the next run \"\n                      f\"tries it again)\")\n\n    def _classify_read(self, tab: Any, body: str) -> tuple[Verdict, str]:\n        \"\"\"Classify a page, reading it once more after the gate's own\n        `retry_after_s` when it was incomplete. Both kinds of list use it.\"\"\"\n        v = classify(self.p, body)\n        if v.outcome == \"incomplete\":\n            retry = next((g.retry_after_s for g in self.p.gates\n                          if g.name == v.gate), 0)\n            if retry:\n                time.sleep(retry)\n                try:\n                    body = self.observe(tab)\n                    v = classify(self.p, body)\n                except ProtocolError:\n                    pass\n        return v, body\n\n    def reload_list(self, main: Any) -> None:\n        \"\"\"Return the queue tab to a good state. The caller MUST re-reach.\n\n        Prefers the profile's `home_url` over a reload. Measured: once the\n        page stops opening rows, reloading does not cure it — the URL\n        carries the stale client state and reloads it too — while going to\n        the base URL cures it at once, and the list comes back a fraction of\n        the size because the rest was accumulated dead DOM.\n\n        A reload returns the tab to wherever its URL points, which is the\n        landing screen and not the list. Three of the four reloads forgot\n        that, so each one undid itself: the page came back unclickable, the\n        next three clicks hit nothing, and a second heal restored what the\n        reload had just destroyed. Measured at 21 heal cycles in one run.\n        \"\"\"\n        if self.p.home_url:\n            try:\n                self.call(\"navigate\", {\"url\": self.p.home_url,\n                                       \"tab_id\": main}, timeout=120)\n                return\n            except ProtocolError:\n                pass          # fall back to a plain reload\n        try:\n            self.call(\"reload\", {\"tab_id\": main})\n        except ProtocolError:\n            pass\n\n    def close_tab(self, tab: Any) -> None:\n        \"\"\"Close a work tab, accepting that it may already be gone.\n\n        A form that submits usually closes its own tab, so the tidy-up finds\n        nothing there. That is the normal end of a successful action, not an\n        error — and letting it escape ended a run that had just approved\n        three items correctly. Every close in the loop goes through here, so\n        the next one added cannot reintroduce the fault.\n        \"\"\"\n        try:\n            self.call(\"close\", {\"tab_id\": tab}, timeout=60)\n        except ProtocolError:\n            pass\n\n    # -- stopping ------------------------------------------------------------\n\n    def clear_stop(self) -> None:\n        \"\"\"Drop a stop left over from a previous run.\n\n        Without this an old stop file would kill the next run before it read\n        a single row, which looks exactly like a hang.\n        \"\"\"\n        _SIGNALLED.clear()\n        try:\n            self.stop_file.unlink()\n        except FileNotFoundError:\n            pass\n        except OSError:\n            pass\n\n    def stop_requested(self) -> str | None:\n        \"\"\"Why the run should wind up, or None to carry on.\"\"\"\n        if self._stop_reason:\n            return self._stop_reason\n        if _SIGNALLED:\n            self._stop_reason = f\"signal ({_SIGNALLED[0]})\"\n        elif self.stop_file.exists():\n            try:\n                who = self.stop_file.read_text(encoding=\"utf-8\").strip()\n            except OSError:\n                who = \"\"\n            self._stop_reason = who or \"asked to stop\"\n        return self._stop_reason\n\n    # -- gated transport ----------------------------------------------------\n\n    def _m(self, verb: str) -> str:\n        \"\"\"The protocol method for a verb on this profile's surface.\"\"\"\n        table = {\n            \"rb\": {\"tabs\": Method.RB_TABS.value, \"observe\": Method.RB_OBSERVE.value,\n                   \"click\": Method.RB_CLICK.value, \"type\": Method.RB_TYPE.value,\n                   \"wait\": Method.RB_WAIT.value, \"close\": Method.RB_CLOSE.value,\n                   \"reload\": Method.RB_RELOAD.value,\n                   \"navigate\": Method.RB_NAVIGATE.value,\n                   \"open\": Method.RB_OPEN.value,\n                   \"act\": Method.RB_ACT.value,\n                   \"cue\": Method.RB_CUE.value},\n            \"browser\": {\"tabs\": Method.BROWSER_TAB_LIST.value,\n                        \"observe\": Method.BROWSER_OBSERVE.value,\n                        \"click\": Method.BROWSER_CLICK.value,\n                        \"type\": Method.BROWSER_TYPE.value,\n                        \"wait\": Method.BROWSER_WAIT.value,\n                        \"close\": Method.BROWSER_TAB_CLOSE.value,\n                        \"reload\": Method.BROWSER_RELOAD.value,\n                        \"navigate\": Method.BROWSER_NAVIGATE.value,\n                        \"open\": Method.BROWSER_TAB_NEW.value},\n        }\n        return table[self.p.surface][verb]\n\n    def call(self, verb: str, params: dict[str, Any] | None = None,\n             timeout: float = 120) -> dict[str, Any]:\n        \"\"\"Every step goes through the daemon: policy checked, audit logged.\"\"\"\n        from .client import call as rpc\n        resp = rpc(self._m(verb), params or {}, home=self.home, timeout=timeout)\n        if not resp.get(\"ok\"):\n            err = resp.get(\"error\") or {}\n            raise ProtocolError(ErrorCode(err.get(\"code\", \"internal\")),\n                                err.get(\"message\", \"failed\"),\n                                hint=err.get(\"hint\"),\n                                effect_state=EffectState(\n                                    err.get(\"effect_state\", \"none\")))\n        return resp.get(\"result\") or {}\n\n    # -- durable record -----------------------------------------------------\n\n    def journal_append(self, **row: Any) -> None:\n        row.setdefault(\"ts\", datetime.now().isoformat(timespec=\"seconds\"))\n        row.setdefault(\"session\", self.tag)\n        row.setdefault(\"profile\", self.p.name)\n        self.journal.parent.mkdir(parents=True, exist_ok=True)\n        with open(self.journal, \"a\", encoding=\"utf-8\") as fh:\n            fh.write(json.dumps(row, ensure_ascii=False) + \"\\n\")\n            fh.flush()\n            os.fsync(fh.fileno())\n\n    def journal_rows(self) -> list[dict[str, Any]]:\n        if not self.journal.exists():\n            return []\n        out: list[dict[str, Any]] = []\n        for line in self.journal.read_text(encoding=\"utf-8\").splitlines():\n            if line.strip():\n                try:\n                    out.append(json.loads(line))\n                except json.JSONDecodeError:\n                    continue\n        return out\n\n    def decided(self) -> set[str]:\n        \"\"\"Full identities already decided — never a display-string prefix.\"\"\"\n        return {str(r.get(\"identity\", \"\")).lower() for r in self.journal_rows()\n                if r.get(\"identity\")\n                and r.get(\"action\") in (\"acted\", \"skipped\", \"committing\")}\n\n    def ledger_row(self, item: str, subject: str, action: str) -> bool:\n        if not self.ledger:\n            return True\n        from .client import call as rpc\n        try:\n            resp = rpc(Method.DESKTOP_TABLE_APPEND.value, {\n                \"file\": str(self.ledger), \"header\": self.p.ledger_header,\n                \"rows\": [f\"{self.tag}\\t{item}\\t{subject}\\t{action}\"],\n                \"dedup\": \"2,3\"}, home=self.home, timeout=120)\n            if resp.get(\"ok\"):\n                # `ok` means the call succeeded, which is NOT the same as a\n                # row being written: dedup refuses a replay and still returns\n                # ok. Counting calls instead of rows made `reconcile` report\n                # \"5 written\" on a run that wrote nothing.\n                return int((resp.get(\"result\") or {}).get(\"rows_added\", 1)) > 0\n            self.emit(f\"  [ledger] not written; the journal holds it \"\n                      f\"({(resp.get('error') or {}).get('message', '?')[:60]})\")\n        except Exception as exc:                  # noqa: BLE001\n            self.emit(f\"  [ledger] not written: {exc} (journal holds it)\")\n        return False\n\n    def reconcile(self) -> dict[str, Any]:\n        \"\"\"Replay the journal into the workbook. Idempotent by construction.\n\n        `--dedup` refuses a row that is already there, so running this twice\n        writes nothing the second time. The counts distinguish the two cases,\n        because \"5 replayed, 0 written\" is the healthy answer on a re-run and\n        would otherwise look like a failure.\n        \"\"\"\n        rows = [r for r in self.journal_rows()\n                if r.get(\"action\") in (\"acted\", \"skipped\")]\n        written = sum(self.ledger_row(r.get(\"summary\", \"\"), r.get(\"subject\", \"\"),\n                                      \"Acted\" if r[\"action\"] == \"acted\" else \"Skipped\")\n                      for r in rows)\n        return {\"effect_state\": (EffectState.COMMITTED.value if written\n                                 else EffectState.NONE.value),\n                \"journal_rows\": len(rows), \"written\": written,\n                \"already_present\": len(rows) - written}\n\n    # -- queue walking ------------------------------------------------------\n\n    def _tab_id(self, t: dict[str, Any]) -> Any:\n        return t.get(\"tabId\", t.get(\"tab_id\"))\n\n    def find_main(self, tabs: list[dict[str, Any]]) -> Any | None:\n        if not self.p.main_tab:\n            return self._tab_id(tabs[0]) if tabs else None\n        for t in tabs:\n            if re.search(self.p.main_tab, str(t.get(\"url\") or \"\")):\n                return self._tab_id(t)\n        return None\n\n    def observe(self, tab: Any, max_tokens: int | None = None) -> str:\n        params: dict[str, Any] = {\"tab_id\": tab, \"max_tokens\": max_tokens}\n        if self.p.read == \"pixels\":\n            # The page may have no readable tree at all: read\n            # it by its pixels then, instead of failing every pass.\n            params[\"fallback\"] = True\n            # Or a tree that answers without the page: add what is\n            # drawn when the tree misses most of it (T10).\n            params[\"ocr\"] = True\n        res = self.call(\"observe\", params, timeout=180)\n        # Where each ref points, when the surface can tell us. Used to\n        # identify a queue row without opening it.\n        self._hrefs = res.get(\"hrefs\") or {}\n        return res.get(\"text\", \"\")\n\n    def identity_of_row(self, ref: str) -> str:\n        \"\"\"The row's identity from its href, or \"\" if it cannot be read.\n\n        Empty means \"unknown\", never \"new\": a row we cannot identify is\n        opened, because skipping work on a hunch is worse than opening\n        it twice.\n        \"\"\"\n        if not (self.p.identity and self.p.identity_in_href):\n            return \"\"\n        href = (getattr(self, \"_hrefs\", {}) or {}).get(ref, \"\")\n        if not href:\n            return \"\"\n        m = re.search(self.p.identity + r\"=([A-Za-z0-9\\-]+)\", href)\n        return m.group(1).lower() if m else \"\"\n\n    def _evidence_missing(self, tab: Any, step: Step) -> str:\n        \"\"\"Did the step change anything? Empty string means it did.\n\n        The single place this question is answered. Three sequence runners\n        needed it and only one had it, which is how a navigation sequence\n        came to report success while never leaving the page it was called\n        to leave.\n\n        It is a bounded WAIT, not a look. The page is polled until the\n        control is gone or `proves_within` (default EVIDENCE_WITHIN_S) runs\n        out. A single look 2s after the click judged a Claim that takes ~18s\n        to have done nothing, and every such request was retired (F-21); the\n        same look failed Approve twice in the T2 run. An effect is missing\n        only when the whole budget has passed without it.\n        \"\"\"\n        if not step.proves:\n            return \"\"\n        within = step.proves_within or EVIDENCE_WITHIN_S\n        deadline = time.monotonic() + within\n        # An evidence wait is a wait the user should SEE: the waiting dots\n        # sit beside the cursor for its duration (S157). Cosmetic only.\n        self._cue_wait(tab, True)\n        try:\n            while True:\n                time.sleep(EVIDENCE_POLL_S)\n                try:\n                    body = self.observe(tab)\n                except ProtocolError:\n                    return \"\"      # the tab went: the step certainly did something\n                if not re.search(step.proves, body):\n                    return \"\"\n                if time.monotonic() >= deadline:\n                    return (f\"{step.proves_label or 'the step had no effect'} \"\n                            f\"(still there after {within:.0f}s)\")\n        finally:\n            self._cue_wait(tab, False)\n\n    def _cue_wait(self, tab: Any, on: bool) -> None:\n        \"\"\"The waiting dots during an evidence wait. A cue that cannot be\n        shown changes nothing about the wait itself.\"\"\"\n        if self.p.surface != \"rb\":\n            return\n        try:\n            self.call(\"cue\", {\"tab_id\": tab, \"wait\": on}, timeout=10)\n        except Exception:\n            pass\n\n    def _press_ladder(self, tab: Any, ref: str, *,\n                      irreversible: bool = False,\n                      opens_tab: bool = False) -> dict[str, Any]:\n        \"\"\"Press through the verified-action ladder (`rb.act`).\n\n        Non-commit: the page must answer, or the error travels like any other\n        and the item's own recovery (restart, `failed`) takes over. Commit:\n        sent once; \"nothing visible changed\" is not a failure here, because\n        the step's `proves` wait - not the ladder - decides `acted`.\n        \"\"\"\n        # The engine has its own proof of every press (the next step's wait,\n        # the commit's `proves`), so a look-only answer is accepted here as\n        # it was in T9/T11; rb.act's recovery still runs for a silent press.\n        # no_visual: the watch's DOM signals (tree, element style/state/text,\n        # expected controls) are its evidence; pixel shots would hide the\n        # whole overlay twice a second for the entire wait - which is exactly\n        # why the cursor \"vanished between clicks\" and the waiting dots never\n        # showed in live runs (S158). No shots, no hide: the cursor persists\n        # and the dots animate through every wait.\n        params: dict[str, Any] = {\"ref\": ref, \"tab_id\": tab,\n                                  \"patience\": self.p.press_patience,\n                                  \"accept_weak\": True, \"no_visual\": True}\n        if irreversible:\n            params[\"irreversible\"] = True\n        if opens_tab:\n            # A list row opens its item in a new tab: only that proves the\n            # press (T7: a style change alone was taken for it, and no tab\n            # came). The list page is never reloaded from here - the engine's\n            # own heal owns that - and a tab appears within seconds.\n            params.update(expect_new_tab=True, no_reload=True,\n                          patience=min(self.p.press_patience,\n                                       max(8.0, self.p.settle_s)))\n        try:\n            res = self.call(\"act\", params, timeout=900)\n        except ProtocolError as exc:\n            if irreversible and exc.error.code == ErrorCode.TIMEOUT:\n                self.emit(\"    ladder: nothing visible after the irreversible \"\n                          \"press (sent once) - its evidence check decides\")\n                return {}\n            raise\n        self.emit(f\"    ladder: {res.get('method')} \"\n                  f\"({res.get('evidence', '?')} evidence, \"\n                  f\"{res.get('waited_s', 0)}s)\")\n        return res\n\n    def _press_near(self, tab: Any, near: str, pick: str, *, nth: int = 1,\n                    irreversible: bool = False,\n                    expect_download: bool = False) -> dict[str, Any]:\n        \"\"\"Press the control in the row of a drawn text (rb.act --near).\n\n        With `expect_download` the step's proof is the new file; an\n        irreversible press whose file never came is UNCONFIRMED - dispatched,\n        not proven - never `acted` and never repeated.\"\"\"\n        params: dict[str, Any] = {\"near\": near, \"pick\": pick or \"right\",\n                                  \"nth\": nth, \"tab_id\": tab,\n                                  \"patience\": self.p.press_patience,\n                                  # DOM evidence only; pixel shots would hide\n                                  # the overlay through every wait (S158).\n                                  \"accept_weak\": True, \"no_visual\": True}\n        if irreversible:\n            params[\"irreversible\"] = True\n        if expect_download:\n            params[\"expect_download\"] = \"~/Downloads\"\n        try:\n            res = self.call(\"act\", params, timeout=900)\n        except ProtocolError as exc:\n            if irreversible and exc.error.code == ErrorCode.TIMEOUT:\n                if expect_download:\n                    raise _Unconfirmed(\"no downloaded file appeared after the \"\n                                       \"press (sent once)\") from exc\n                self.emit(\"    ladder: nothing visible after the irreversible \"\n                          \"press (sent once) - its evidence check decides\")\n                return {}\n            raise\n        # The same line as a ref press, plus what was pressed: in T10 the\n        # row opens left no trace in the run log (S141).\n        target = f\" - {res['target']}\" if res.get(\"target\") else \"\"\n        self.emit(f\"    ladder: {res.get('method')} \"\n                  f\"({res.get('evidence', '?')} evidence, \"\n                  f\"{res.get('waited_s', 0)}s){target}\")\n        for f in res.get(\"downloaded\") or []:\n            self.emit(f\"    downloaded: {f}\")\n        return res\n\n    def _click(self, tab: Any, ref: str, *,\n               opens_tab: bool = False) -> dict[str, Any]:\n        \"\"\"Every non-commit click of the engine: one event, or the ladder.\"\"\"\n        if self.p.press == \"ladder\":\n            return self._press_ladder(tab, ref, opens_tab=opens_tab)\n        return self.call(\"click\", {\"ref\": ref, \"tab_id\": tab})\n\n    def _wait_step(self, tab: Any, step: Step, prev_click: Step | None) -> None:\n        \"\"\"Wait for a control, pressing the click that should produce it once\n        more if the first press was swallowed (T5-1).\n\n        Only a NON-commit click is ever pressed again, and only while its own\n        control is still on the page - a control that has gone did its job,\n        and the wait simply continues. The irreversible step is never\n        repeated by this or any other path.\n        \"\"\"\n        rc = step.reclick_after if step.reclick_after >= 0 else RECLICK_AFTER_S\n        first = step.timeout\n        if (prev_click is not None and not prev_click.commit\n                and prev_click.pattern and rc and rc < step.timeout):\n            first = rc\n        params = {\"name\": step.name, \"role\": step.role or None, \"tab_id\": tab}\n        try:\n            self.call(\"wait\", {**params, \"timeout\": first}, timeout=first + 30)\n            return\n        except ProtocolError as exc:\n            if first >= step.timeout or exc.error.code != ErrorCode.TIMEOUT:\n                raise\n        body = self.observe(tab)\n        m = re.search(prev_click.pattern, body) if prev_click else None\n        if m:\n            self.emit(f\"    {step.name!r} not there after {first:.0f}s and the \"\n                      f\"control that should produce it is still on the page - \"\n                      f\"pressing it once more\")\n            self._click(tab, m.group(1))\n        rest = max(15.0, step.timeout - first)\n        self.call(\"wait\", {**params, \"timeout\": rest}, timeout=rest + 30)\n\n    def _reopen_main(self) -> bool:\n        \"\"\"The main tab is gone: open `home_url` again, at most every\n        MAIN_REOPEN_EVERY_S. True when a tab was opened.\"\"\"\n        if not self.p.home_url:\n            return False\n        now = time.monotonic()\n        if (self._main_reopened_at is not None\n                and now - self._main_reopened_at < MAIN_REOPEN_EVERY_S):\n            return False\n        self._main_reopened_at = now\n        try:\n            self.call(\"open\", {\"url\": self.p.home_url}, timeout=120)\n        except ProtocolError as exc:\n            self.emit(f\"the main tab is gone and reopening it failed: \"\n                      f\"{exc.error.message}\")\n            return False\n        self.emit(\"the queue's main tab was gone - reopened the profile's \"\n                  \"home_url\")\n        return True\n\n    def _run_steps(self, tab: Any, body: str,\n                   steps: list[Step]) -> tuple[str, str]:\n        \"\"\"Run a sequence with no commit semantics.\n\n        Returns (last body, failure). `failure` is \"\" only when every step\n        that had to run did: a required step that matched nothing, a click\n        the surface refused, a press the page did not answer, or an effect\n        that never showed each fail it.\n        `optional` means the control may be ABSENT - not that a refused\n        click is fine. The caller judges success by this, never by whether\n        rows happen to be on screen (F-24: the landing page shows preview\n        rows while the bell click was refused under an overlay, so the\n        sequence \"succeeded\" and every following click was dead).\n\n        Used for navigation, where nothing is irreversible. The acting\n        sequence has its own runner because it must journal the intent\n        before the one step that cannot be undone.\n        \"\"\"\n        failure = \"\"\n        prev_click: Step | None = None\n        for step in steps:\n            try:\n                if step.kind == \"sleep\":\n                    time.sleep(step.seconds or 1)\n                    continue\n                if step.kind == \"observe\":\n                    body = self.observe(tab)\n                    continue\n                if step.kind == \"wait\":\n                    self._wait_step(tab, step, prev_click)\n                    prev_click = None\n                    continue\n                m = re.search(step.pattern, body) if step.pattern else None\n                if not m:\n                    if not step.optional:\n                        self.emit(f\"    reach: nothing matched \"\n                                  f\"{step.pattern[:40]!r}\")\n                        failure = failure or (f\"nothing matched \"\n                                              f\"{step.pattern[:40]!r}\")\n                    continue\n                if step.kind == \"click\":\n                    before = body\n                    self._click(tab, m.group(1))\n                    prev_click = step\n                else:\n                    self.call(\"type\", {\"text\": step.text,\n                                       \"ref\": m.group(1), \"tab_id\": tab})\n                    prev_click = None\n                why = self._evidence_missing(tab, step)\n                if why:\n                    # Everything after this depends on the step having\n                    # worked, so carrying on would only hide the cause.\n                    self.emit(f\"    reach: {why} - the sequence cannot \"\n                              f\"continue from here\")\n                    return self.observe(tab), why\n                body = self.observe(tab)\n                if step.kind == \"click\" and not step.proves \\\n                        and self._page_unanswered(before, body):\n                    # The reach's post-condition, read off the page itself\n                    # (F-24). A press the surface ACCEPTED can still do\n                    # nothing - swallowed under an overlay - and rows on\n                    # screen cannot say so: the landing page shows preview\n                    # rows either way. A navigation press that the page\n                    # answered always changes something in the read; one\n                    # more look after a beat, then a press that changed\n                    # nothing counts as the failure it is, so the retry\n                    # fires instead of the run walking a dead list.\n                    time.sleep(EVIDENCE_POLL_S)\n                    body = self.observe(tab)\n                    if self._page_unanswered(before, body):\n                        why = (f\"{m.group(0)[:50]!r} was pressed and the \"\n                               f\"page did not change\")\n                        self.emit(f\"    reach: {why} - the sequence cannot \"\n                                  f\"continue from here\")\n                        return body, why\n            except ProtocolError as exc:\n                self.emit(f\"    reach: {exc.error.message[:70]}\")\n                failure = exc.error.message[:120]\n                break\n        # Observe once more, AFTER the last step. Sequences end with a settle\n        # (`sleep`), and only clicks and types re-observed, so the body\n        # returned described the page mid-navigation. Its `@eNN` refs were\n        # then stale - and a stale ref is worse than a missing one, because\n        # refs are re-issued on every observation, so an old one can resolve\n        # to a different element: the click lands, the probe is satisfied,\n        # and something else entirely was pressed.\n        try:\n            return self.observe(tab), failure\n        except ProtocolError as exc:\n            return body, failure or exc.error.message[:120]\n\n    @staticmethod\n    def _page_unanswered(before: str, after: str) -> bool:\n        \"\"\"Two reads of the same page, with the refs folded out.\n\n        Refs are re-issued on every observation, so raw text can differ on a\n        page that did nothing; everything else is stable when nothing\n        happened. Used to tell a press the page answered from one it\n        swallowed (F-24).\n        \"\"\"\n        fold = lambda s: re.sub(r\"@e\\d+\", \"@e\", s)          # noqa: E731\n        return fold(before) == fold(after)\n\n    def reach_list(self, tab: Any, body: str) -> str:\n        \"\"\"Bring the queue back into view when its items are not showing.\n\n        An empty queue and a page that has navigated away look identical\n        from here: neither contains the item pattern. Without this the\n        engine slept through a full worklist because the tab happened to\n        be on a detail page.\n        \"\"\"\n        if not self.p.reach:\n            return body\n        self.emit(\"  items not visible - running the profile's reach \"\n                  \"sequence to bring the list back\")\n        # Analyse the page before acting on it: the reach starts from one\n        # page, and a run can begin anywhere - T12 (S143) began on the list\n        # the previous task left open, and pressed for \"Document Records\",\n        # which only the home page has, for four minutes.\n        start = self._reach_start(body)\n        if start and self.p.home_url:\n            self.emit(f\"    reach: the page does not offer where the reach \"\n                      f\"starts ({start}) - going to home_url first\")\n            self.reload_list(tab)\n            time.sleep(RELOAD_SETTLE_S)\n            try:\n                body = self.observe(tab)\n            except ProtocolError:\n                pass\n        failure = \"\"\n        went_home = bool(start and self.p.home_url)\n        for attempt in (1, 2, 3):\n            if attempt == 3:\n                # Two tries here did not bring the list (a press refused, or\n                # pressed and the rows never came): the page may have looked\n                # right and not been. Home once, then try again.\n                if went_home or not self.p.home_url:\n                    break\n                self.emit(\"    reach: failed twice here - going to home_url \"\n                          \"and trying once more\")\n                self.reload_list(tab)\n                time.sleep(RELOAD_SETTLE_S)\n                try:\n                    body = self.observe(tab)\n                except ProtocolError:\n                    pass\n            body, failure = self._run_steps(tab, body, self.p.reach)\n            # Success is the SEQUENCE completing and the rows being there.\n            # Rows alone proved nothing: the landing page shows preview rows\n            # even when the bell click was refused under the rQuick overlay,\n            # so the retry never ran and every click after it was dead\n            # (F-24, the F-01 lesson: in the tree is not reachable).\n            if not failure and re.search(self.p.item, body):\n                return body\n            if attempt == 1:\n                # Usually an overlay that was still painting: the probe\n                # refuses to click through it — rightly — and by the time it\n                # clears the sequence has been abandoned. A bounded retry\n                # costs nothing when the first attempt works, unlike a longer\n                # sleep, which pays its full cost on every page for ever.\n                self.emit(f\"    reach: {failure or 'nothing yet'} - one more \"\n                          f\"attempt\")\n                time.sleep(8)\n                try:\n                    body = self.observe(tab)\n                except ProtocolError:\n                    pass\n        if failure:\n            self.emit(f\"    reach: failed ({failure}) - rows on screen \"\n                      f\"may not be clickable\")\n        return body\n\n    def _reach_start(self, body: str) -> str:\n        \"\"\"What the reach needs to find first, if this page does not offer\n        it; \"\" when it does (or when the reach begins with something that\n        needs no control). Optional steps are looked past: they may be absent\n        anywhere.\"\"\"\n        for step in self.p.reach:\n            if step.optional or step.kind in (\"sleep\", \"observe\"):\n                continue\n            if step.kind == \"wait\":\n                return \"\" if step.name and step.name in body else (step.name or \"\")\n            if step.near:\n                return \"\" if step.near in body else step.near\n            if step.pattern:\n                return \"\" if re.search(step.pattern, body) else step.pattern\n            return \"\"\n        return \"\"\n\n    def _survey(self, body: str) -> None:\n        \"\"\"Analyse the list once, and say where the profile disagrees.\n\n        A declared pattern that matches nothing used to be a silent\n        no-op: the pagination loop broke on its first iteration, the\n        queue was never expanded, and the run reported healthy progress\n        through a fraction of it. Saying so out loud is the whole fix.\n        \"\"\"\n        try:\n            from .analyse import analyse\n            a = analyse(body)\n        except Exception:\n            return\n        items = len(re.findall(self.p.item, body))\n        self.emit(f\"  survey: {a['refs']} refs, {items} item(s) matched\"\n                  + (\"  [OBSERVATION TRUNCATED]\" if a[\"truncated\"] else \"\"))\n        if a[\"truncated\"]:\n            self.emit(\"  ! the read was cut short - rows below the cut \"\n                      \"are invisible to every pattern\")\n        if not items and a[\"repeating\"]:\n            top = a[\"repeating\"][0]\n            self.emit(f\"  ! item pattern matched NOTHING. The page's \"\n                      f\"most common shape is {top['count']}x \"\n                      f\"{top['role']}: {top['pattern']}\")\n        if self.p.load_more:\n            if not re.search(self.p.load_more, body):\n                found = \", \".join(f\"{p['name']!r}\" for p in a[\"pagination\"])\n                self.emit(f\"  ! load_more pattern matched NOTHING, so the \"\n                          f\"list is never expanded. Controls that DO \"\n                          f\"exist here: {found or 'none found'}\")\n        elif a[\"pagination\"]:\n            found = \", \".join(f\"{p['name']!r}\" for p in a[\"pagination\"])\n            self.emit(f\"  ! no load_more declared, but the page offers: \"\n                      f\"{found} - the queue may be larger than it looks\")\n        for n in a[\"notes\"]:\n            self.emit(\"  ! \" + n)\n\n    def run(self, *, minutes: float = 60.0, max_items: int = 0,\n            max_acted: int = 0) -> dict[str, Any]:\n        deadline = time.monotonic() + minutes * 60\n        decided = self.decided()\n        self.emit(f\"profile {self.p.name!r} on the {self.p.surface} surface; \"\n                  f\"{len(decided)} item(s) already decided\")\n        if self.dry_run:\n            self.emit(\"DRY RUN - classified and recorded, never committed\")\n\n        pos, notab, seen, acted = 1, 0, 0, 0\n        surveyed = False          # analyse the list once, not every pass\n        force_reach = False       # clicks are failing: re-navigate, do\n                                  # not trust that rows look reachable\n        stale = 0                 # consecutive rows already decided\n        # One stale-list reload per pass, then walk. Decided items that were\n        # skipped are never actioned, so they stay in the queue for good; a\n        # block of them at the head is not \"the list is behind\" - it is the\n        # list. Reloading and starting again at row 1 met the same block\n        # every time: 3 identical cycles, furthest row 7, nothing new (F-23).\n        stale_heal_spent = False\n        # ...and once per pass is still for ever when every pass finds\n        # nothing: the end-of-queue reset re-armed the heal, so the reload\n        # came back each pass with the same block and 0 new rows. The heal\n        # is re-armed only by forward progress since it fired (a new\n        # decision or a new item examined); a reload cycle with none leaves\n        # it spent, and the run says so once - loudly, and in the journal -\n        # instead of looping on the reload (F-23).\n        heal_mark: tuple[int, int, int] | None = None\n        stuck_reported = False\n        self.clear_stop()\n        install_signal_stop()\n        while time.monotonic() < deadline:\n            stop = self.stop_requested()\n            if stop:\n                self.emit(f\"stopping: {stop}\")\n                break\n            if max_items and seen >= max_items:\n                self.emit(f\"item budget reached ({max_items})\")\n                break\n            if max_acted and acted >= max_acted:\n                # The budget that matters on a live run: this one counts\n                # the steps that cannot be taken back.\n                self.emit(f\"action budget reached ({max_acted} acted)\")\n                self._stop_reason = f\"action budget ({max_acted})\"\n                break\n            try:\n                tabs = self.call(\"tabs\", timeout=60).get(\"tabs\", [])\n            except ProtocolError as exc:\n                self.emit(f\"cannot list tabs: {exc.error.message}; waiting\")\n                time.sleep(15)\n                continue\n            main = self.find_main(tabs)\n            if main is None:\n                if self._reopen_main():\n                    time.sleep(20)     # measured: home takes ~18s to settle\n                    force_reach = True\n                    continue\n                self.emit(\"the queue's main tab is not open; waiting\")\n                time.sleep(15)\n                continue\n            for t in tabs:                          # one work tab at a time\n                if self._tab_id(t) != main:\n                    try:\n                        self.close_tab(self._tab_id(t))\n                    except ProtocolError:\n                        pass\n\n            try:\n                body = self.observe(main)\n            except ProtocolError as exc:\n                self.emit(f\"cannot read the queue: {exc.error.message}\")\n                time.sleep(10)\n                continue\n\n            for _ in range(15):                     # paginate to exhaustion\n                if not self.p.load_more:\n                    break\n                m = re.search(self.p.load_more, body)\n                if not m:\n                    break\n                try:\n                    self._click(main, m.group(1))\n                    time.sleep(3)\n                    body = self.observe(main)\n                except ProtocolError:\n                    break\n\n            if not surveyed:\n                surveyed = True\n                self._survey(body)\n            if force_reach:\n                # Rows can be in the tree and still not clickable - a\n                # collapsed panel looks exactly like an open one from\n                # here. Repeated dead clicks are the evidence; trust\n                # them over the row count.\n                force_reach = False\n                body = self.reach_list(main, body)\n            items = re.findall(self.p.item, body)\n            if not items:\n                body = self.reach_list(main, body)\n                items = re.findall(self.p.item, body)\n            if not items:\n                self.emit(\"queue is empty; waiting\")\n                time.sleep(30)\n                continue\n            if pos > len(items):\n                self.emit(f\"end of queue ({len(items)}); resetting for arrivals\")\n                pos = 1\n                if (stale_heal_spent and heal_mark is not None\n                        and len(decided) == heal_mark[0]\n                        and seen == heal_mark[1]):\n                    # The reload met the same decided block and the walk\n                    # past it found nothing new: the block IS the list, not\n                    # staleness. Keep the heal spent; re-arming it here is\n                    # what looped (F-23). Walking past the block still\n                    # works, so the run goes on - but it says so once, in\n                    # the journal too, the way any other stuck state is\n                    # reported, rather than reloading for ever.\n                    if not stuck_reported:\n                        stuck_reported = True\n                        self.emit(f\"  STUCK: the stale-list heal reloaded \"\n                                  f\"into the same decided block (furthest \"\n                                  f\"row {heal_mark[2]}, 0 new) - walking \"\n                                  f\"past it; no more reloads for it until \"\n                                  f\"the walk finds new work\")\n                        self.journal_append(\n                            action=\"stuck\",\n                            summary=f\"stale-list heal made no progress: the \"\n                                    f\"reload returned the same decided \"\n                                    f\"block (furthest row {heal_mark[2]}, \"\n                                    f\"0 new); walking past it, heal not \"\n                                    f\"re-armed\")\n                else:\n                    # No heal was spent this pass, or the pass after one\n                    # found new work: a future stale block may be real\n                    # staleness, so the heal may fire once again.\n                    stale_heal_spent = False\n                    heal_mark = None\n                    stuck_reported = False\n                time.sleep(20)\n                continue\n\n            # Skip rows whose identity the LIST already gives us. Before\n            # this, every decided row still cost an open and a close.\n            skipped_free = 0\n            while pos <= len(items):\n                cand = items[pos - 1]\n                cref = cand[0] if isinstance(cand, tuple) else cand\n                cid = (self.text_identity(cref)\n                       if self.p.opens == \"same-tab\" and self.p.identity_from == \"text\"\n                       else self.identity_of_row(cref))\n                if cid and (cid in decided or cid in self._held):\n                    pos += 1\n                    skipped_free += 1\n                    continue\n                break\n            if skipped_free:\n                self.emit(f\"  skipped {skipped_free} already-decided row(s) \"\n                          f\"from the list, without opening any\")\n            if pos > len(items):\n                self.emit(\"every visible row is already decided; \"\n                          \"reloading for new arrivals\"\n                          + (f\" ({len(self._held)} held: unreadable)\"\n                             if self._held else \"\"))\n                self.reload_list(main)\n                # Measured: going home takes ~18s to become usable.\n                # The reach waits for its controls too, but do not\n                # make the first wait absorb a shortfall we know of.\n                time.sleep(20)\n                force_reach = True   # a reload lands on the landing\n                                     # screen; the list must be re-reached\n                pos = 1\n                continue\n\n            row = items[pos - 1]\n            ref = row[0] if isinstance(row, tuple) else row\n            name = (row[1] if isinstance(row, tuple) and len(row) > 1 else \"\")\n            self.emit(f\"[{pos}/{len(items)}] opening {ref} {name}\".rstrip())\n\n            if self.p.opens == \"same-tab\":\n                done, was_seen, did_act = self._same_tab_item(main, ref, decided)\n                seen += was_seen\n                acted += did_act\n                pos += 0 if did_act else 1\n                force_reach = True            # the list is reached again\n                if max_acted and acted >= max_acted:\n                    self.emit(f\"action budget reached ({max_acted} acted)\")\n                    self._stop_reason = f\"action budget ({max_acted})\"\n                    break\n                continue\n\n            try:\n                self._click(main, ref, opens_tab=True)\n            except ProtocolError as exc:\n                self.emit(f\"  could not open it: {exc.error.message}\")\n                pos += 1\n                continue\n            time.sleep(self.p.settle_s)\n\n            try:\n                after = self.call(\"tabs\", timeout=60).get(\"tabs\", [])\n            except ProtocolError:\n                after = []\n            work = [t for t in after if self._tab_id(t) != main]\n            if not work:\n                notab += 1\n                self.emit(f\"  no work tab appeared ({notab}/3)\")\n                if notab >= 3:\n                    # A reload alone made this worse: it returns to the\n                    # landing screen, so the list has to be reached\n                    # again rather than assumed.\n                    self.emit(\"  3x no-tab -> the list is not actually \"\n                              \"reachable; reloading and re-navigating\")\n                    self.reload_list(main)\n                    time.sleep(20)   # see above: measured ~18s\n                    notab = 0\n                    force_reach = True\n                    pos = 1\n                    continue\n                pos += 1\n                continue\n            notab = 0\n\n            tab = self._tab_id(work[0])\n            identity = \"\"\n            if self.p.identity:\n                m = re.search(self.p.identity + r\"=([A-Za-z0-9\\-]+)\",\n                              str(work[0].get(\"url\") or \"\"))\n                identity = m.group(1).lower() if m else \"\"\n            suffix = f\" [{identity[:8]}]\" if identity else \"\"\n\n            if identity and identity in decided:\n                self.emit(f\"  already decided earlier ({identity[:8]}); closing\")\n                self.close_tab(tab)\n                pos += 1\n                stale += 1\n                # Opening rows only to find they are old may mean the list\n                # is behind the truth, and one reload re-sorts new arrivals\n                # into view. Only one: if the block is still there after\n                # it, these rows are simply decided items that stay in the\n                # queue, and the way on is past them.\n                if stale >= STALE_ROWS_BEFORE_RELOAD and not stale_heal_spent:\n                    self.emit(f\"  {stale} decided rows in a row - the list \"\n                              f\"may be stale; reloading it once\")\n                    heal_mark = (len(decided), seen, pos)\n                    self.reload_list(main)\n                    time.sleep(20)   # see above: measured ~18s\n                    force_reach = True   # ditto - see reload_list\n                    stale, pos = 0, 1\n                    stale_heal_spent = True\n                elif stale == STALE_ROWS_BEFORE_RELOAD:\n                    self.emit(f\"  {stale} decided rows in a row again after \"\n                              f\"a reload - they stay in the queue; walking \"\n                              f\"past them\")\n                continue\n            stale = 0\n            if identity and identity in self._held:\n                self.emit(f\"  held this run ({identity[:8]}): unreadable \"\n                          f\"{UNREAD_HOLD_AFTER} times; closing\")\n                self.close_tab(tab)\n                pos += 1\n                continue\n\n            try:\n                body = self.observe(tab)\n            except ProtocolError as exc:\n                self.emit(f\"  cannot read it: {exc.error.message}\")\n                self.close_tab(tab)\n                pos += 1\n                continue\n\n            v, body = self._classify_read(tab, body)\n            self._note_read(identity, v.outcome == \"incomplete\")\n\n            seen += 1\n            summary = f\"{v.label}{suffix}\"\n            if v.outcome != \"act\":\n                # An unreadable page is not a decision about the request.\n                # The complete gate is fail-closed and right to refuse, but\n                # its refusal means \"I could not read this\", not \"this one\n                # is excluded\" - and `skipped` + `decided` would retire the\n                # request for ever without it ever being judged.\n                transient = v.outcome == \"incomplete\"\n                self.emit(f\"  {'UNREAD' if transient else 'SKIP'} \"\n                          f\"{v.subject or name}: {summary}\")\n                self.journal_append(\n                    action=\"failed\" if transient else \"skipped\",\n                    identity=identity, subject=v.subject or name,\n                    summary=summary, gate=v.gate, verdict=v.outcome)\n                if not transient:\n                    self.ledger_row(summary, v.subject or name, \"Skipped\")\n                    if identity:\n                        decided.add(identity)\n                self.close_tab(tab)\n                pos += 1\n                continue\n\n            if self.dry_run:\n                self.emit(f\"  DRY RUN would act on {v.subject or name}: {summary}\")\n                self.journal_append(action=\"dry-run\", identity=identity,\n                                    subject=v.subject or name, summary=summary)\n                if identity:\n                    decided.add(identity)\n                self.close_tab(tab)\n                pos += 1\n                continue\n\n            # Last chance to stop before the first irreversible click.\n            # A stop arriving after this point lets THIS item finish\n            # rather than leaving a decision half-entered.\n            stop = self.stop_requested()\n            if stop:\n                self.emit(f\"stopping before acting on \"\n                          f\"{v.subject or name}: {stop}\")\n                self.close_tab(tab)\n                break\n\n            ok = self._execute(tab, body, identity, v, summary, name)\n            acted += ok\n            if ok and identity:\n                # Remember it NOW, not just in the journal. A row that\n                # has just been actioned is still on screen, and the\n                # cursor holds here on purpose, so without this the\n                # next pass reopened it and began a second irreversible\n                # sequence. Observed live: the only thing that stopped a\n                # double approval was the site having withdrawn its own\n                # Approve button.\n                decided.add(identity)\n            self.close_tab(tab)\n            if not ok:\n                # The cursor holds after a SUCCESSFUL action, because an\n                # actioned row leaves the queue and the rest shift up. A\n                # failed row is still there, so holding meant reopening\n                # it until the clock ran out and never reaching anything\n                # behind it. Most failures here are simply items\n                # assigned to someone else.\n                pos += 1\n                continue\n            if max_acted and acted >= max_acted:\n                # Checked here too, so the budget binds immediately\n                # rather than after one more item is opened and read.\n                self.emit(f\"action budget reached ({max_acted} acted)\")\n                self._stop_reason = f\"action budget ({max_acted})\"\n                break\n            time.sleep(3)\n            # An actioned row leaves the queue, so the cursor stays put.\n            if (self.p.maintenance_every\n                    and acted % self.p.maintenance_every == 0):\n                # The profile asks for the queue to be refreshed after every\n                # N actions (oracle-cpi: after each request). Going home\n                # discards the ADF client state that a plain reload keeps,\n                # and the list is reached again from row 1; decided rows\n                # are skipped from the list for free, so the walk back\n                # costs no opens.\n                self.emit(f\"  refreshing the queue after {acted} action(s) \"\n                          f\"(maintenance every {self.p.maintenance_every})\")\n                self.reload_list(main)\n                time.sleep(20)   # measured: home takes ~18s to settle\n                force_reach = True\n                pos = 1\n\n        self.clear_stop()\n        return {\"effect_state\": EffectState.NONE.value, \"examined\": seen,\n                \"acted\": acted, \"journal\": str(self.journal),\n                \"profile\": self.p.name,\n                \"stopped\": self._stop_reason}\n\n    @staticmethod\n    def text_identity(text: str) -> str:\n        \"\"\"An identity for an item that has no id in any URL: its row text,\n        case- and space-folded.\"\"\"\n        return re.sub(r\"\\s+\", \" \", str(text or \"\")).strip().lower()[:120]\n\n    def _same_tab_item(self, main: Any, anchor: str,\n                       decided: set[str]) -> tuple[bool, int, int]:\n        \"\"\"One item of a same-tab list: open it by the control of its row,\n        read, classify, act or record, then return to the list (home_url, and\n        the caller re-runs the reach). Returns (handled, seen, acted).\"\"\"\n        identity = (self.text_identity(anchor)\n                    if self.p.identity_from == \"text\" else \"\")\n        suffix = f\" [{identity[:24]}]\" if identity else \"\"\n        if identity and identity in decided:\n            self.emit(f\"  already decided earlier{suffix}; next row\")\n            return True, 0, 0\n        if identity and identity in self._held:\n            self.emit(f\"  held this run{suffix}: unreadable \"\n                      f\"{UNREAD_HOLD_AFTER} times; next row\")\n            return True, 0, 0\n        try:\n            self._press_near(main, anchor, self.p.open_pick)\n        except ProtocolError as exc:\n            self.emit(f\"  could not open it: {exc.error.message}\")\n            return False, 0, 0\n        time.sleep(self.p.settle_s)\n        try:\n            body = self.observe(main)\n        except ProtocolError as exc:\n            self.emit(f\"  cannot read it: {exc.error.message}\")\n            self.reload_list(main)\n            return False, 0, 0\n        v, body = self._classify_read(main, body)\n        self._note_read(identity, v.outcome == \"incomplete\")\n        summary = f\"{v.label}{suffix}\"\n        if v.outcome != \"act\":\n            transient = v.outcome == \"incomplete\"\n            self.emit(f\"  {'UNREAD' if transient else 'SKIP'} {v.subject or anchor}: {summary}\")\n            self.journal_append(action=\"failed\" if transient else \"skipped\",\n                                identity=identity, subject=v.subject or anchor,\n                                summary=summary, gate=v.gate, verdict=v.outcome)\n            if not transient:\n                self.ledger_row(summary, v.subject or anchor, \"Skipped\")\n                if identity:\n                    decided.add(identity)\n            self.reload_list(main)\n            return True, 1, 0\n        if self.dry_run:\n            self.emit(f\"  DRY RUN would act on {v.subject or anchor}: {summary}\")\n            self.journal_append(action=\"dry-run\", identity=identity,\n                                subject=v.subject or anchor, summary=summary)\n            if identity:\n                decided.add(identity)\n            self.reload_list(main)\n            return True, 1, 0\n        stop = self.stop_requested()\n        if stop:\n            self.emit(f\"stopping before acting on {v.subject or anchor}: {stop}\")\n            self.reload_list(main)\n            return True, 1, 0\n        ok = self._execute(main, body, identity, v, summary, anchor)\n        if ok and identity:\n            decided.add(identity)\n        self.reload_list(main)\n        return True, 1, int(bool(ok))\n\n    def reload_item(self, tab: Any, why: str) -> str | None:\n        \"\"\"Reload an ITEM tab and read it again; None if that failed.\n\n        Never the list: a list tab goes home through `reload_list`, because\n        its URL carries the stale state. An item tab is the opposite - its\n        URL names the task, so a reload returns to the same item, and it is\n        what repairs a wedged Claim/Approve toolbar (field-verified on ADF).\n        \"\"\"\n        self.emit(f\"  {why[:90]} - nothing irreversible was sent; reloading \"\n                  f\"the item once and starting its steps again\")\n        try:\n            self.call(\"reload\", {\"tab_id\": tab})\n            time.sleep(RELOAD_SETTLE_S)\n            return self.observe(tab)\n        except ProtocolError:\n            return None\n\n    def _execute(self, tab: Any, body: str, identity: str, v: Verdict,\n                 summary: str, name: str) -> int:\n        \"\"\"Run the declared sequence. The `commit` step is journalled first.\n\n        A failure BEFORE the commit step may reload the item once and start\n        its steps again (`reload_to_recover`): nothing irreversible has been\n        sent. After the `committing` line is written, nothing is retried.\n        \"\"\"\n        subject = v.subject or name\n        self.emit(f\"  ACTING on {subject}: {summary}\")\n        committing = False\n        restarted = False\n        while True:\n            try:\n                prev_click: Step | None = None\n                for step in self.p.steps:\n                    if step.kind == \"sleep\":\n                        time.sleep(step.seconds or 1)\n                        continue\n                    if step.kind == \"observe\":\n                        body = self.observe(tab)\n                        continue\n                    if step.kind == \"wait\":\n                        self._wait_step(tab, step, prev_click)\n                        prev_click = None\n                        continue\n\n                    if step.near:\n                        ref = \"\"                          # found by its row\n                    else:\n                        m = re.search(step.pattern, body) if step.pattern else None\n                        if not m:\n                            body = self.observe(tab)      # one patient re-read\n                            m = re.search(step.pattern, body) if step.pattern else None\n                        if not m:\n                            if step.optional:\n                                continue\n                            raise ProtocolError(\n                                ErrorCode.TARGET_NOT_FOUND,\n                                f\"step {step.kind!r} found nothing matching \"\n                                f\"{step.pattern[:50]!r}\")\n                        ref = m.group(1)\n\n                    if step.commit:\n                        # Durable BEFORE the irreversible click. A lost row, a\n                        # crash or a power cut can never hide that it happened.\n                        committing = True\n                        self.journal_append(action=\"committing\", identity=identity,\n                                            subject=subject, summary=summary)\n                    if step.kind == \"click\":\n                        if step.near:\n                            self._press_near(tab, step.near, step.pick,\n                                             nth=step.nth,\n                                             irreversible=step.commit,\n                                             expect_download=step.expect_download)\n                        elif self.p.press == \"ladder\":\n                            self._press_ladder(tab, ref, irreversible=step.commit)\n                        else:\n                            self.call(\"click\", {\"ref\": ref, \"tab_id\": tab})\n                        prev_click = step\n                    else:\n                        self.call(\"type\", {\"text\": step.text, \"ref\": ref,\n                                           \"tab_id\": tab})\n                        prev_click = None\n                    # Re-read before the next step matches anything. Without\n                    # this each step searched the page as it was BEFORE the\n                    # previous one changed it, and the \"patient re-read\" below\n                    # never rescued it: a stale body usually DOES match, because\n                    # the old control is still in the old text. The ref that\n                    # comes out of such a match belongs to a page that no longer\n                    # exists, and refs are re-issued on every observation - so it\n                    # can resolve to a different element and the wrong thing is\n                    # pressed, in the sequence that presses Approve and Submit.\n                    try:\n                        body = self.observe(tab)\n                    except ProtocolError:\n                        pass          # tab gone: the commit check handles it\n                    if step.commit:\n                        # Confirm BEFORE claiming it happened. The wait inside\n                        # the evidence check replaces the fixed 10s sleep that\n                        # used to come first: a slow Submit is now waited for\n                        # instead of being filed as unconfirmed. Writing\n                        # `acted` on faith would record an approval that a\n                        # swallowed click never made, and `decided` would close\n                        # the item for ever.\n                        why = self._evidence_missing(tab, step)\n                        if why:\n                            raise _Unconfirmed(why)\n                        self.journal_append(action=\"acted\", identity=identity,\n                                            subject=subject, summary=summary)\n                        self.ledger_row(summary, subject, \"Acted\")\n                    else:\n                        # The control that had to disappear. Checking now costs\n                        # one observation; not checking costs the timeout of\n                        # every later step that depended on it.\n                        why = self._evidence_missing(tab, step)\n                        if why:\n                            raise _NoEffect(why)\n                self.emit(f\"  ACTED on {subject}: {summary}\")\n                return 1\n            except _Unconfirmed as why:\n                # Say it loudly and write nothing more. The `committing` line\n                # already on disk is the correct record of an unknown outcome.\n                self.emit(f\"  UNCONFIRMED on {subject}: {why} - the journal \"\n                          f\"keeps it as dispatched-but-unconfirmed, which is \"\n                          f\"what is actually known. Check it by hand.\")\n                return 0\n            except _NoEffect as why:\n                if not committing and not restarted and self.p.reload_to_recover:\n                    restarted = True\n                    fresh = self.reload_item(tab, str(why))\n                    if fresh is not None:\n                        body = fresh\n                        continue\n                # Not a malfunction, and not a decision either: the effect did\n                # not show within its budget, which is equally what a swallowed\n                # click looks like. Retryable, so no ledger row and nothing\n                # added to `decided` - the journal and this run now agree (the\n                # old `skipped` retired the item in the journal while the run\n                # carried on as if it had not, F-22).\n                label = f\"{why} - {summary}\"\n                self.emit(f\"  NO EFFECT on {subject}: {why} - left for a \"\n                          f\"later run\")\n                self.journal_append(action=\"failed\", identity=identity,\n                                    subject=subject, summary=label,\n                                    verdict=\"no-effect\")\n                return 0\n            except ProtocolError as exc:\n                if not committing and not restarted and self.p.reload_to_recover:\n                    restarted = True\n                    fresh = self.reload_item(tab, exc.error.message)\n                    if fresh is not None:\n                        body = fresh\n                        continue\n                self.emit(f\"  sequence stopped: {exc.error.message}\")\n                self.journal_append(action=\"failed\", identity=identity,\n                                    subject=subject, summary=summary,\n                                    error=exc.error.message,\n                                    effect_state=exc.error.effect_state.value)\n                return 0\n");
